const adminAuth=(req,res,next)=>{try{const token=jwt.verify((req.get('authorization')||'').replace(/^Bearer /,''),process.env.JWT_SECRET);const user=db.prepare('SELECT id,username,name,role,active FROM app_user WHERE id=?').get(token.sub);if(!user?.active)throw new Error();req.user=user;req.scopes=userScopes(db,user);next();}catch{res.status(401).json({error:'unauthorized'});}};
const installationAuth=(req,res,next)=>{const value=(req.get('authorization')||'').replace(/^Bearer /,'');if(!process.env.INSTALLATION_KEY||value!==process.env.INSTALLATION_KEY)return res.status(401).json({error:'invalid_installation_key'});next();};
