app.post('/api/v1/admin/me/api-token',adminAuth,(req,res)=>{const productIds=[...new Set((req.body.productIds||[]).map(Number))],channels=[...new Set(req.body.channels||[])];if(!productIds.length||!channels.length)return res.status(400).json({error:'scope_required'});if(channels.some(channel=>!CHANNELS.includes(channel)))return res.status(400).json({error:'invalid_channel'});const allowed=allowedProducts(req).map(product=>product.id);if(!req.scopes.all&&productIds.some(id=>!allowed.includes(id)))return res.status(403).json({error:'scope_denied'});const token=`ci_${crypto.randomBytes(32).toString('base64url')}`,hash=crypto.createHash('sha256').update(token).digest('hex');db.transaction(()=>{db.prepare('UPDATE app_user SET api_token_hash=?,api_token_created_at=CURRENT_TIMESTAMP WHERE id=?').run(hash,req.user.id);db.prepare('DELETE FROM api_token_product WHERE user_id=?').run(req.user.id);db.prepare('DELETE FROM api_token_channel WHERE user_id=?').run(req.user.id);for(const productId of productIds)db.prepare('INSERT INTO api_token_product(user_id,product_id) VALUES(?,?)').run(req.user.id,productId);for(const channel of channels)db.prepare('INSERT INTO api_token_channel(user_id,channel) VALUES(?,?)').run(req.user.id,channel);})();res.status(201).json({token,productIds,channels});});
