app.post('/api/v1/ci/artifacts',ciAuth,upload.single('artifact'),(req,res,next)=>{const file=req.file;try{if(!file||path.extname(file.originalname).toLowerCase()!=='.zip')throw new Error('zip_required');const productCode=textValue(req.body.product)||'pdv',version=textValue(req.body.version),channel=textValue(req.body.channel);if(!version)throw new Error('version_required');if(!CHANNELS.includes(channel))throw new Error('invalid_channel');const product=db.prepare('SELECT id FROM product WHERE code=? AND active=1').get(productCode);if(!product)throw new Error('product_not_found');if(!canAccess(req.scopes,product.id,channel)){if(file?.path&&fs.existsSync(file.path))fs.unlinkSync(file.path);return res.status(403).json({error:'scope_denied'});}const id=crypto.randomUUID(),relativePath=`.incoming/${id}.zip`,storedPath=path.join(packagesPath,relativePath);fs.renameSync(file.path,storedPath);const sha256=hashFileSync(storedPath),sizeBytes=fs.statSync(storedPath).size;db.prepare('INSERT INTO ci_artifact(id,user_id,product_code,version,channel,file_path,original_name,sha256,size_bytes) VALUES(?,?,?,?,?,?,?,?,?)').run(id,req.user.id,productCode,version,channel,relativePath,file.originalname,sha256,sizeBytes);res.status(201).json({id,product:productCode,version,channel,fileName:file.originalname,sha256,sizeBytes,status:'pending'});}catch(e){if(file?.path&&fs.existsSync(file.path))fs.unlinkSync(file.path);next(e);}});
app.post('/api/v1/updates/check',installationAuth,(req,res)=>{try{const reg=registerInstallation(req.body),{product='pdv',channel='production',currentVersion='0.0.0'}=req.body;
 const releases=db.prepare(`SELECT DISTINCT r.* FROM release r JOIN product p ON p.id=r.product_id JOIN release_target rt ON rt.release_id=r.id WHERE p.code=? AND r.channel=? AND r.active=1 AND r.blocked=0 AND (rt.target_type='all' OR (rt.target_type='client' AND rt.client_id=?)) ORDER BY r.published_at DESC,r.id DESC`).all(product,channel,reg.client.id);
 const release=releases.find(r=>compareVersions(r.version,currentVersion)>0),policy=getReleasePolicy(release),status=release?'update_available':'no_update',message=release?`Versão ${release.version} disponível (${release.artifact_type})${policy.deadlineExpired?' e obrigatória por prazo vencido':''}.`:'Terminal já está atualizado.';
 db.prepare('INSERT INTO terminal_event(terminal_id,release_id,previous_version,target_version,status,message,ip) VALUES(?,?,?,?,?,?,?)').run(reg.terminal.id,release?.id||null,currentVersion,release?.version||null,status,message,req.ip);
 if(!release)return res.json({available:false,currentVersion});res.json({available:true,releaseId:String(release.id),version:release.version,mandatory:policy.mandatory,mandatoryReason:policy.mandatoryReason,deadlineAt:release.deadline_at,deadlineExpired:policy.deadlineExpired,minimumVersion:release.minimum_version,artifactType:release.artifact_type||'package',fileName:release.original_name||path.basename(release.file_path),downloadUrl:`${downloadBase}/${release.file_path}`,sha256:release.sha256,sizeBytes:release.size_bytes,notes:release.show_notes_pdv?release.technical_notes:null,showNotesPdv:Boolean(release.show_notes_pdv)});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/v1/updates/events',installationAuth,(req,res)=>{const t=db.prepare('SELECT id FROM terminal WHERE external_id=?').get(req.body.terminalId);if(!t)return res.status(404).json({error:'terminal_not_found'});const release=req.body.targetVersion?db.prepare(`SELECT r.id FROM release r JOIN product p ON p.id=r.product_id WHERE r.version=? AND p.code=? ORDER BY r.id DESC LIMIT 1`).get(req.body.targetVersion,req.body.product||'pdv'):null;db.prepare('INSERT INTO terminal_event(terminal_id,release_id,previous_version,target_version,status,message,ip) VALUES(?,?,?,?,?,?,?)').run(t.id,release?.id||null,req.body.previousVersion||null,req.body.targetVersion||null,req.body.status,req.body.message||null,req.ip);res.status(202).json({accepted:true});});
app.post('/api/v1/errors',installationAuth,(req,res)=>{let decrypted;try{const body=req.body||{},terminalId=normalizeKeyTerminalId(body.terminalId);if(!terminalId)throw new Error('terminal_id_required');decrypted=decryptEnvelope(terminalId,body);const diagnostic=JSON.parse(decrypted.plain.toString('utf8')),exceptionClass=textValue(diagnostic.exceptionClass||diagnostic.exception),message=textValue(diagnostic.message);if(!exceptionClass)throw new Error('exception_required');if(!message)throw new Error('message_required');const terminal=db.prepare('SELECT id,product_code FROM terminal WHERE lower(trim(external_id))=?').get(terminalId),product=terminal?.product_code||textValue(body.product)||'pdv',setting=db.prepare('SELECT store_screenshot FROM error_setting WHERE id=1').get(),rawScreenshot=diagnostic.screenshotBase64??diagnostic.base64??diagnostic.print,screenshot=setting?.store_screenshot?normalizeScreenshot(rawScreenshot):null;if(screenshot)diagnostic.screenshotBase64=`data:${screenshot.mime};base64,${screenshot.base64}`;else delete diagnostic.screenshotBase64;delete diagnostic.base64;delete diagnostic.print;const encrypted=encryptErrorPayload(terminalId,diagnostic),result=db.prepare('INSERT INTO application_error(terminal_id,product_code,occurred_at,exception_class,message,screenshot_mime,ip,key_terminal_id,crypto_salt,crypto_iv,crypto_auth_tag,encrypted_payload) VALUES(?,?,CURRENT_TIMESTAMP,?,?,?,?,?,?,?,?,?)').run(terminal?.id||null,product,'<encrypted>','<encrypted>',screenshot?.mime||null,req.ip,terminalId,encrypted.salt,encrypted.iv,encrypted.authTag,encrypted.ciphertext);res.status(201).json({accepted:true,id:Number(result.lastInsertRowid),screenshotStored:Boolean(screenshot)});}catch(e){res.status(400).json({error:e.message});}finally{if(decrypted){decrypted.plain.fill(0);decrypted.key.fill(0);decrypted.ciphertext.fill(0);}}});
