function notifyReleasePublished(releaseId,product,channel,version){
 const admins=db.prepare(`SELECT id FROM app_user WHERE active=1 AND role='admin'`).all();
 const title=`Nova versão ${version}`;
 const message=`${product.name} publicou a versão ${version} no canal ${channel}.`;
 const insert=db.prepare('INSERT INTO admin_notification(user_id,type,title,message,release_id) VALUES(?,?,?,?,?)');
 for(const admin of admins){
  const scopes=userScopes(db,admin);
  if(canAccess(scopes,product.id,channel))insert.run(admin.id,'release_published',title,message,releaseId);
 }
}
