  const source=ciArtifact?path.resolve(packagesPath,ciArtifact.file_path):file.path;if(ciArtifact&&(!source.startsWith(incomingPath+path.sep)||!fs.existsSync(source)))throw new Error('artifact_file_not_found');
  const rootFiles=(req.files?.rootFiles||[]).map(item=>({originalname:item.originalname,data:fs.readFileSync(item.path)}));
  manifest=buildUpdatePackageFromZip(source,final,{product:product.code,channel:req.body.channel,version,releaseId:createdReleaseId,rootFiles});moved=true;size=fs.statSync(final).size;sha=await hashFile(final);
  db.transaction(()=>{db.prepare('UPDATE release SET sha256=?,size_bytes=? WHERE id=?').run(sha,size,createdReleaseId);db.prepare('INSERT INTO terminal_event(release_id,status,message,ip) VALUES(?,?,?,?)').run(createdReleaseId,'published',`Versão ${version} publicada como pacote de arquivos, com ${manifest.files.length} arquivo(s) e prazo até ${deadlineAt}.`,req.ip);if(ciArtifact)db.prepare('UPDATE ci_artifact SET consumed_at=CURRENT_TIMESTAMP WHERE id=?').run(ciArtifact.id);notifyReleasePublished(createdReleaseId,product,req.body.channel,version);})();
  if(ciArtifact&&fs.existsSync(source))fs.unlinkSync(source);
