app.patch('/api/v1/admin/releases/:id',adminAuth,(req,res)=>{const release=db.prepare('SELECT * FROM release WHERE id=?').get(req.params.id);if(!release)return res.status(404).json({error:'release_not_found'});if(!canAccess(req.scopes,release.product_id,release.channel))return res.status(403).json({error:'scope_denied'});const active=req.body.active===undefined?release.active:(req.body.active?1:0),blocked=req.body.blocked===undefined?release.blocked:(req.body.blocked?1:0);db.prepare('UPDATE release SET active=?,blocked=? WHERE id=?').run(active,blocked,release.id);res.json({updated:true,active:Boolean(active),blocked:Boolean(blocked)});});
