app.post('/api/v1/admin/releases/:id/copy',adminAuth,(req,res)=>{const source=db.prepare('SELECT * FROM release WHERE id=?').get(req.params.id);if(!source)return res.status(404).json({error:'release_not_found'});const channel=req.body.channel;if(!CHANNELS.includes(channel))return res.status(400).json({error:'invalid_channel'});if(!canAccess(req.scopes,source.product_id,source.channel)||!canAccess(req.scopes,source.product_id,channel))return res.status(403).json({error:'scope_denied'});const ids=(req.body.targetClientIds||[]).map(Number),targetType=req.body.targetType==='client'?'client':'all';if(targetType==='client'&&!ids.length)return res.status(400).json({error:'target_required'});const id=db.transaction(()=>{const r=db.prepare(`INSERT INTO release(product_id,version,channel,file_path,sha256,size_bytes,mandatory,minimum_version,notes,technical_notes,show_notes_pdv,artifact_type,original_name,deadline_at,published_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(source.product_id,req.body.version||source.version,channel,source.file_path,source.sha256,source.size_bytes,req.body.mandatory?1:0,req.body.minimumVersion||source.minimum_version,req.body.notes??source.notes,req.body.technicalNotes??source.technical_notes,req.body.showNotesPdv===undefined?source.show_notes_pdv:(req.body.showNotesPdv?1:0),source.artifact_type,source.original_name,normalizeFutureDeadline(req.body.deadlineAt),req.user.id);if(targetType==='all')db.prepare("INSERT INTO release_target(release_id,target_type) VALUES(?,'all')").run(r.lastInsertRowid);else for(const clientId of ids)db.prepare("INSERT INTO release_target(release_id,target_type,client_id) VALUES(?,'client',?)").run(r.lastInsertRowid,clientId);return r.lastInsertRowid;})();res.status(201).json({id});});
